const CELLS = [];
Object.keys(D).forEach(lv => D[lv].cells.forEach(c => {
  c.level = lv;
  if (!c.r) {
    const xs = c.p.map(p => p[0]);
    const ys = c.p.map(p => p[1]);
    c.r = [Math.min(...xs), Math.min(...ys), Math.max(...xs) - Math.min(...xs), Math.max(...ys) - Math.min(...ys)];
  }
  CELLS.push(c);
}));

function has(id) { return CELLS.some(c => c.id === id); }

function parseRoom(room) {
  const s = String(room || "").toLowerCase();
  if (/offsite/.test(s)) return {kind: "offsite", level: "l1", ids: []};
  const named = [
    [/innovation theater/, "10"], [/networking caf/, "5"], [/sketchup gallery/, "2"], [/trimble park/, "3"],
    [/gamification/, "4"], [/dog park/, "6"], [/coffee lounge/, "7"], [/start-?up/, "9"],
    [/trimble solutions/, "8"], [/main entrance/, "1"]
  ];
  for (const [re, id] of named) {
    if (re.test(s)) return {kind: "room", level: "expo", ids: [id]};
  }
  if (/ballroom/.test(s)) {
    const m = s.match(/section\s+([a-l])\b|\bballroom\s+([a-l])\b/);
    const sec = m ? (m[1] || m[2]).toUpperCase() : "";
    return {kind: "room", level: "l2", ids: sec ? [sec] : ["A", "B", "C", "D", "L", "E", "K", "F", "J", "I", "H", "G"]};
  }
  if (/expo/.test(s)) return {kind: "vague", level: "expo", ids: []};
  let t = s.toUpperCase().replace(/&/g, " AND ");
  t = t.replace(/(\d{3,4})\s*A\s+AND\s+B/g, "$1A $1B");
  const found = [...t.matchAll(/\d{3,4}(?:\s*[AB]\b)?/g)].map(m => m[0].replace(/\s+/g, ""));
  const ids = [];
  found.forEach(id => {
    if (has(id)) ids.push(id);
    else if (has(id + "A")) ids.push(id + "A", id + "B");
  });
  const hit = CELLS.find(c => c.id === ids[0]);
  const level = hit ? hit.level
    : /bassano|titian|veronese|bellini|ballroom/.test(s) ? "l2"
    : /lido|murano|san polo|toscana/.test(s) ? "l3"
    : "l1";
  return {kind: ids.length ? "room" : "unknown", level, ids: [...new Set(ids)]};
}

function ordinal(col, n) {
  if (col === 0) return "the left end";
  if (col === n - 1) return "the right end";
  const word = ["", "second", "third", "fourth", "fifth", "sixth"][col] || "";
  if (col < n / 2 && word) return word + " from the left";
  const rword = ["", "second", "third", "fourth", "fifth"][n - 1 - col] || "";
  return rword ? rword + " from the right" : "near the middle";
}

function describe(sess) {
  if (!sess) return "Pick a session to mark its room.";
  if (sess.kind === "offsite") return sess.r + " is not in the Venetian. The Offsite Expo is a bus ride of about 45 minutes, and a visit takes 4 to 5 hours. Bus times are in the Dimensions app.";
  if (sess.kind === "vague") return sess.r + " is in the Expo Hall. The catalog does not give a zone, so ask at the Main Entrance or open Maps in the Dimensions app.";
  const hits = CELLS.filter(c => sess.ids.includes(c.id));
  const c0 = hits[0];
  if (!c0) return "I can't place " + sess.r + " on this map. Open Maps in the Dimensions app for the official plan.";
  if (c0.level === "expo") return EXPO_SAY[c0.id] || sess.r;
  const names = [...new Set(hits.map(c => c.id))].sort((a, b) => a.localeCompare(b, "en", {numeric: true}));
  const verb = names.length > 1 ? " are on " : " is on ";
  if (c0.b === "Venetian Ballroom") {
    if (sess.ids.length > 1) return "The Venetian Ballroom is the large maroon hall on the left of Level 2. This session uses the whole ballroom.";
    return "Section " + c0.id + " of the Venetian Ballroom is on Level 2, " + ["top row", "second row", "third row", "bottom row"][c0.row] + ".";
  }
  if (c0.area) return (c0.b === "Room" ? "Room " : c0.b + " ") + names.join(" and ") + verb + FLOOR[c0.level] + ", " + c0.area + ".";
  const cols = hits.map(c => c.col);
  const lo = Math.min(...cols);
  const hi = Math.max(...cols);
  const row = c0.half ? (c0.half === "A" ? "the upper half of the leftmost room" : "the lower half of the leftmost room") : (c0.row === 0 ? "the upper row" : "the lower row");
  const where = c0.half ? "" : ", " + (lo === hi ? ordinal(lo, c0.n) : (hi >= c0.n - 1 ? "the right end" : lo === 0 ? "the left end" : "the middle"));
  return c0.b + " " + names.join(" and ") + verb + FLOOR[c0.level] + ", " + row + where + ".";
}

function el(name, attrs, text) {
  const n = document.createElementNS(NS, name);
  Object.keys(attrs || {}).forEach(k => n.setAttribute(k, attrs[k]));
  if (text != null) n.textContent = text;
  return n;
}

function html(tag, cls, text) {
  const n = document.createElement(tag);
  if (cls) n.className = cls;
  if (text != null) n.textContent = text;
  return n;
}

